llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Flupirtine, a carbamate-substituted aminopyridine with a fluorobenzyl group, has 90% oral bioavailability in healthy volunteers; the query shares the carbamate-aminopyridine/pyrimidine motif and fluorobenzyl substituent, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "SB-681323, a fused heteroaromatic p38 inhibitor with fluorophenyl groups, has approximately 50% systemic availability in humans; its pyrimidine-like heteroaromatic core is analogous to the query's aminopyrimidine-pyrazolopyridine, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "BAY 41-4109, a heteroaromatic drug containing a methyl carbamate/ester and fluorophenyl groups, has 48% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CC-292, a pyrimidine-based kinase inhibitor, showed excellent oral bioavailability in humans; the query's 2,4-diaminopyrimidine core is a related kinase-inhibitor scaffold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Flubendazole, a benzimidazole-2-carbamate, has low oral bioavailability in humans; although it shares the methyl carbamate, its poorly soluble benzimidazole scaffold is less transferable to the query's aminopyrimidine system.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Mebendazole has very low oral bioavailability (4.4%) in a human volunteer; this low-F benzimidazole carbamate evidence is only weakly transferable to the query because of the different heteroaromatic core.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a carbamate-substituted aminopyrimidine with a fluorobenzyl-pyrazolopyridine, more analogous to orally bioavailable kinase inhibitors and flupirtine than to poorly absorbed benzimidazole carbamates. Multiple direct human F measurements in related scaffolds (48-90%) outweigh the low-F benzimidazole evidence, so predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "Morgan similarities to all evidence molecules are low (<0.27), limiting transferability.",
    "Some retrieved records have apparent SMILES/text mismatches (e.g., C11, C25) and were not weighted.",
    "Solubility, permeability, and metabolic stability of the query are not directly known."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

